-- ---------------------------------------------------------------------------------------------
-- Functions (v1, rewritten)
-- ---------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.can_access_meeting(p_meeting_id uuid, p_min_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM meetings m
    WHERE m.id = p_meeting_id
      AND (
        -- meeting owner
        m.user_id = public.app_user_id()
        -- OR owner of the folder the meeting is in
        OR (
          m.folder_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM folders f
            WHERE f.id = m.folder_id AND f.user_id = public.app_user_id()
          )
        )
        -- OR shared member with sufficient role
        OR (
          m.folder_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM folder_shares fs
            WHERE fs.folder_id = m.folder_id
              AND fs.user_id = public.app_user_id()
              AND (p_min_role = 'viewer' OR fs.role = 'editor')
          )
        )
      )
  )
$function$;

CREATE OR REPLACE FUNCTION public.claim_next_job(p_worker_id text)
 RETURNS SETOF jobs
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.jobs
  SET    status     = 'running',
         locked_at  = now(),
         locked_by  = p_worker_id,
         updated_at = now()
  WHERE  id = (
    SELECT id FROM public.jobs
    WHERE  status    = 'queued'
      AND  run_after <= now()
    ORDER  BY run_after ASC
    LIMIT  1
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
$function$;

CREATE OR REPLACE FUNCTION public.jobs_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;

CREATE OR REPLACE FUNCTION public.match_transcript_chunks(query_embedding vector, match_count integer DEFAULT 6, filter_meeting_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, meeting_id uuid, content text, start_ms integer, end_ms integer, similarity double precision)
 LANGUAGE sql
 STABLE
AS $function$
  select
    c.id,
    c.meeting_id,
    c.content,
    c.start_ms,
    c.end_ms,
    1 - (c.embedding <=> query_embedding) as similarity
  from transcript_chunks c
  where filter_meeting_id is null or c.meeting_id = filter_meeting_id
  order by c.embedding <=> query_embedding
  limit match_count;
$function$;

CREATE OR REPLACE FUNCTION public.match_transcript_chunks(query_embedding vector, match_count integer DEFAULT 6, filter_meeting_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(id uuid, meeting_id uuid, content text, start_ms integer, end_ms integer, similarity double precision)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  -- Keep scanning the HNSW index until enough post-filtered rows are found.
  -- Guarded: older pgvector (< 0.8.0) has no such GUC — ignore in that case.
  BEGIN
    PERFORM set_config('hnsw.iterative_scan', 'strict_order', true);
  EXCEPTION WHEN OTHERS THEN
    -- GUC not available on this pgvector version; ef_search below still helps.
    NULL;
  END;

  -- Widen the candidate list (default 40). Cheap at our scale, much better recall.
  PERFORM set_config('hnsw.ef_search', '200', true);

  RETURN QUERY
    SELECT c.id, c.meeting_id, c.content, c.start_ms, c.end_ms,
           1 - (c.embedding <=> query_embedding) AS similarity
    FROM   transcript_chunks c
    WHERE  filter_meeting_ids IS NULL
       OR  c.meeting_id = ANY(filter_meeting_ids)
    ORDER BY c.embedding <=> query_embedding
    LIMIT  match_count;
END;
$function$;

-- v2 version of v1 migration 001's trigger function (ARC-02). v1 read the PostgREST setting
-- request.jwt.claims; v2 reads the RLS request context. Same rule: no user context
-- (service/worker) may change roles, a user context must be an admin.
CREATE FUNCTION public.prevent_role_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.role is distinct from new.role then
    -- No request context = service-role or superuser call → allow role changes.
    if public.app_user_id() is null then
      return new;
    end if;
    if coalesce(public.app_user_role(), 'user') <> 'admin' then
      raise exception 'Only admins can change user roles'
        using errcode = 'P0001',
              hint    = 'Use the /admin/users route to change roles.';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.quota_apply_movement(p_user_id uuid, p_delta_audio_seconds bigint, p_delta_agent_queries integer, p_reason text, p_dedup_key text, p_allow_overdraw boolean, p_meeting_id uuid, p_created_by uuid, p_metadata jsonb)
 RETURNS TABLE(status text, audio_remaining bigint, agent_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_audio  bigint;
  v_agent  int;
BEGIN
  -- 1. Idempotency: if this dedup_key was already applied, return current
  --    balances without making any changes.
  IF p_dedup_key IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM quota_ledger WHERE dedup_key = p_dedup_key
    ) THEN
      SELECT audio_seconds_remaining, agent_queries_remaining
        INTO v_audio, v_agent
        FROM quota_wallets
       WHERE user_id = p_user_id;

      -- Wallet may not exist yet if a prior run created the ledger row but
      -- crashed before upserting the wallet. Treat missing wallet as zeros.
      RETURN QUERY SELECT 'already_applied'::text,
                          COALESCE(v_audio, 0)::bigint,
                          COALESCE(v_agent, 0)::int;
      RETURN;
    END IF;
  END IF;

  -- 2. Ensure wallet row exists. First-use lazy creation; the backfill at the
  --    bottom of this migration covers all pre-existing users.
  INSERT INTO quota_wallets (user_id, audio_seconds_remaining, agent_queries_remaining)
  VALUES (p_user_id, 0, 0)
  ON CONFLICT (user_id) DO NOTHING;

  -- 3. Attempt the balance update.
  --
  --    When p_allow_overdraw = false, the WHERE clause enforces that neither
  --    axis goes below zero. Positive (top-up) deltas always satisfy these
  --    conditions, so this branch handles all calls correctly — top-ups never
  --    fail here.
  --
  --    The conditional UPDATE is race-free: if two concurrent agent queries
  --    both land here simultaneously, only the one that wins the write wins
  --    the lock; the other sees ROW_COUNT = 0 and returns 'insufficient'.
  IF NOT p_allow_overdraw THEN
    UPDATE quota_wallets
       SET audio_seconds_remaining = audio_seconds_remaining + p_delta_audio_seconds,
           agent_queries_remaining = agent_queries_remaining + p_delta_agent_queries,
           updated_at              = now()
     WHERE user_id = p_user_id
       AND audio_seconds_remaining + p_delta_audio_seconds >= 0
       AND agent_queries_remaining + p_delta_agent_queries >= 0;

    IF NOT FOUND THEN
      -- At least one axis would go negative. Return current balances; make
      -- NO ledger insert (the movement did not happen).
      SELECT audio_seconds_remaining, agent_queries_remaining
        INTO v_audio, v_agent
        FROM quota_wallets
       WHERE user_id = p_user_id;

      RETURN QUERY SELECT 'insufficient'::text, v_audio, v_agent;
      RETURN;
    END IF;

  ELSE
    -- Top-up or overdraw-allowed settle (e.g. post-generate real-duration
    -- adjustment that may push slightly below zero due to estimation error).
    UPDATE quota_wallets
       SET audio_seconds_remaining = audio_seconds_remaining + p_delta_audio_seconds,
           agent_queries_remaining = agent_queries_remaining + p_delta_agent_queries,
           updated_at              = now()
     WHERE user_id = p_user_id;
  END IF;

  -- 4. Write the ledger row. Only reached when the wallet update succeeded.
  INSERT INTO quota_ledger (
    user_id,
    delta_audio_seconds,
    delta_agent_queries,
    reason,
    dedup_key,
    meeting_id,
    created_by,
    metadata
  ) VALUES (
    p_user_id,
    p_delta_audio_seconds,
    p_delta_agent_queries,
    p_reason,
    p_dedup_key,
    p_meeting_id,
    p_created_by,
    COALESCE(p_metadata, '{}'::jsonb)
  );

  -- 5. Read and return the new balances.
  SELECT audio_seconds_remaining, agent_queries_remaining
    INTO v_audio, v_agent
    FROM quota_wallets
   WHERE user_id = p_user_id;

  RETURN QUERY SELECT 'applied'::text, v_audio, v_agent;
END;
$function$;

