CREATE INDEX audit_logs_created_at_idx ON public.audit_logs USING btree (created_at DESC);
CREATE INDEX audit_logs_target_idx ON public.audit_logs USING btree (target_type, target_id);
CREATE INDEX idx_calsug_meeting ON public.calendar_suggestions USING btree (meeting_id);
CREATE INDEX idx_chat_messages_session ON public.chat_messages USING btree (session_id, created_at);
CREATE INDEX chat_sessions_folder_id_idx ON public.chat_sessions USING btree (user_id, folder_id) WHERE (folder_id IS NOT NULL);
CREATE INDEX idx_chat_sessions_meeting ON public.chat_sessions USING btree (meeting_id);
CREATE INDEX idx_chat_sessions_user ON public.chat_sessions USING btree (user_id);
CREATE INDEX features_module_prefix_idx ON public.features USING btree (module_prefix);
CREATE INDEX features_status_idx ON public.features USING btree (status);
CREATE INDEX folder_shares_folder_id ON public.folder_shares USING btree (folder_id);
CREATE INDEX folder_shares_user_id ON public.folder_shares USING btree (user_id);
CREATE INDEX folders_user_id ON public.folders USING btree (user_id);
CREATE UNIQUE INDEX folders_user_name_ci ON public.folders USING btree (user_id, lower(name));
CREATE INDEX folders_user_position ON public.folders USING btree (user_id, "position");
CREATE INDEX jobs_claim_idx ON public.jobs USING btree (run_after) WHERE (status = 'queued'::text);
CREATE INDEX jobs_meeting_idx ON public.jobs USING btree (meeting_id);
CREATE INDEX jobs_stuck_idx ON public.jobs USING btree (locked_at) WHERE (status = 'running'::text);
CREATE INDEX idx_meetings_created_at ON public.meetings USING btree (created_at DESC);
CREATE INDEX idx_meetings_status ON public.meetings USING btree (status);
CREATE INDEX idx_meetings_user_id ON public.meetings USING btree (user_id);
CREATE INDEX meetings_folder_id ON public.meetings USING btree (folder_id);
CREATE INDEX meetings_retention_purge_idx ON public.meetings USING btree (created_at) WHERE ((status = 'done'::meeting_status) AND (audio_path IS NOT NULL));
CREATE INDEX meetings_user_pin_sort ON public.meetings USING btree (user_id, pinned_at DESC NULLS LAST, created_at DESC);
CREATE UNIQUE INDEX quota_ledger_dedup_key_idx ON public.quota_ledger USING btree (dedup_key) WHERE (dedup_key IS NOT NULL);
CREATE INDEX quota_ledger_user_created_idx ON public.quota_ledger USING btree (user_id, created_at DESC);
CREATE INDEX storage_config_provider_status ON public.storage_config USING btree (provider, status, created_at DESC);
CREATE INDEX idx_todos_meeting ON public.todos USING btree (meeting_id);
CREATE INDEX idx_todos_status ON public.todos USING btree (status);
CREATE INDEX idx_chunks_embedding ON public.transcript_chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX idx_chunks_meeting ON public.transcript_chunks USING btree (meeting_id);
CREATE INDEX idx_segments_meeting ON public.transcript_segments USING btree (meeting_id, segment_index);
CREATE INDEX usage_log_created_at_idx ON public.usage_log USING btree (created_at DESC);
CREATE INDEX usage_log_key_id_idx ON public.usage_log USING btree (key_id) WHERE (key_id IS NOT NULL);
CREATE INDEX usage_log_meeting_id_idx ON public.usage_log USING btree (meeting_id) WHERE (meeting_id IS NOT NULL);
CREATE INDEX usage_log_operation_idx ON public.usage_log USING btree (operation);
CREATE INDEX usage_log_provider_idx ON public.usage_log USING btree (provider, model);
CREATE INDEX usage_log_status_idx ON public.usage_log USING btree (status) WHERE (status <> 'ok'::text);

-- ---------------------------------------------------------------------------------------------
-- Comments (v1)
-- ---------------------------------------------------------------------------------------------
COMMENT ON COLUMN public.meetings.source IS 'How the audio arrived: "recorded" = in-browser capture, "uploaded" = audio file, "video" = video file (audio extracted server-side).';
COMMENT ON COLUMN public.meetings.storage_provider IS 'Object-storage backend for audio_path: "supabase" = legacy Supabase Storage, "r2" = Cloudflare R2 (CST-02+).';
COMMENT ON TABLE public.profiles IS 'One row per auth.users entry. Stores username and role (synced with app_metadata).';

